\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Venue Color Theme ──
\definecolor{primary}{HTML}{F59E0B}     % Amber
\definecolor{secondary}{HTML}{F43F5E}   % Coral
\definecolor{accent}{HTML}{38BDF8}      % Sky Blue
\definecolor{bgposter}{HTML}{0F172A}    % Slate 900 (Deep Navy)
\definecolor{cardbg}{HTML}{1E293B}      % Slate 800
\definecolor{cardtitlebg}{HTML}{0F172A}
\definecolor{textlight}{HTML}{F8FAFC}
\definecolor{textgray}{HTML}{94A3B8}

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Card styles ──
\tcbset{
  ambercard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.3},
    coltext=textlight
  },
  coralcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.3},
    coltext=textlight
  },
  bluecard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.3},
    coltext=textlight
  },
  highlightcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=secondary!15!bgposter,
    borderline west={6pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=secondary,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.4},
    coltext=textlight
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=4mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=bgposter, colframe=bgposter, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  halign=center, valign=center,
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{72}{86}\selectfont\bfseries THE STATE OF GLOBAL EDUCATION}\\[12pt]
  {\fontsize{32}{40}\selectfont\color{primary} PROGRESS, GAPS, AND INEQUALITY}\\[12pt]
  {\fontsize{24}{32}\selectfont\color{textgray} A comparative look at the world's expansion of education access and the critical gaps that remain.}
}

% ══ BIG STAT BANNER ══
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=4pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=center, borderline south={6pt}{0pt}{secondary},
  drop shadow={opacity=0.3}
]{name=stats, column=1, span=2, between=row3 and row6}{
  \centering
  \vspace{10pt}
  {\fontsize{110}{120}\selectfont\bfseries\color{secondary} 244 MILLION}\\[12pt]
  {\fontsize{32}{40}\selectfont\color{textlight} Children of official school age still out of school globally.}\\[12pt]
  {\fontsize{26}{32}\selectfont\color{textgray} Including 60 million primary-age and 184 million secondary-age children (2023).}
  \vspace{10pt}
}

% ══ COLUMN 1 ══
\posterbox[ambercard, title={Two Centuries of Educational Expansion}
]{name=col1a, column=1, between=row6 and row12}{
  \fontsize{28}{38}\selectfont
  A dramatic reversal in access to education over the past 200 years:
  \vspace{16pt}

  \begin{center}
  \colorbox{primary!20!bgposter}{\parbox{0.92\linewidth}{
    \centering\vspace{12pt}
    {\fontsize{52}{64}\selectfont\bfseries\color{primary} 1800}\\[8pt]
    {\fontsize{28}{36}\selectfont \textbf{< 1 in 5} adults possessed basic education}\vspace{12pt}
  }}
  \end{center}
  \vspace{8pt}
  \begin{center}
  \colorbox{primary!20!bgposter}{\parbox{0.92\linewidth}{
    \centering\vspace{12pt}
    {\fontsize{52}{64}\selectfont\bfseries\color{primary} TODAY}\\[8pt]
    {\fontsize{28}{36}\selectfont \textbf{> 4 in 5} adults possess basic education}\vspace{12pt}
  }}
  \end{center}
  \vspace{16pt}
  \begin{itemize}[itemsep=12pt]
    \item Education transformed from an elite luxury to a global norm.
    \item Global literacy rates have followed a nearly identical trajectory.
  \end{itemize}
}

\posterbox[coralcard, title={The Learning Crisis}
]{name=col1b, column=1, between=row12 and row16}{
  \fontsize{28}{38}\selectfont
  Enrollment numbers hide a stark reality: \textbf{Being in school $\neq$ learning}.
  \vspace{16pt}

  \begin{center}
  \colorbox{secondary!20!bgposter}{\parbox{0.92\linewidth}{
    \centering\vspace{12pt}
    {\fontsize{52}{64}\selectfont\bfseries\color{secondary} < 20\%}\\[8pt]
    {\fontsize{28}{36}\selectfont Achieve minimum reading proficiency in low-income countries}\vspace{12pt}
  }}
  \end{center}

  \vspace{16pt}
  \begin{itemize}
    \item Majority cannot identify key ideas in a simple text by end of primary school.
  \end{itemize}
}

\posterbox[bluecard, title={Closing the Gender Gap}
]{name=col1c, column=1, between=row16 and bottom}{
  \fontsize{28}{38}\selectfont
  Historically, boys were far more likely to attend school. Today:
  \vspace{16pt}

  \renewcommand{\arraystretch}{1.6}
  \begin{center}
  \begin{tabular}{p{0.35\linewidth} p{0.55\linewidth}}
    \rowcolor{accent!15!bgposter} \textbf{Primary} & Nearly closed globally \\
    \textbf{Secondary} & Nearly closed globally \\
    \rowcolor{accent!15!bgposter} \textbf{Tertiary} & Women exceed men globally \\
  \end{tabular}
  \end{center}
  \vspace{16pt}
  \begin{itemize}
    \item \textbf{Exception:} Significant disparities persist in nations like Afghanistan.
  \end{itemize}
}

% ══ COLUMN 2 ══
\posterbox[coralcard, title={A World Divided: Quality of Schooling}
]{name=col2a, column=2, between=row6 and row14}{
  \fontsize{28}{38}\selectfont
  Combining quantity and quality of education reveals massive inequality.
  \vspace{24pt}

  {\fontsize{32}{40}\selectfont\bfseries\color{secondary} Learning-Adjusted Years (2020)}
  \vspace{16pt}

  \begin{center}
  \colorbox{secondary!20!bgposter}{\parbox{0.92\linewidth}{
    \centering\vspace{16pt}
    {\fontsize{60}{72}\selectfont\bfseries\color{secondary} < 3 YEARS}\\[12pt]
    {\fontsize{28}{36}\selectfont \textbf{Poorest Countries} (parts of Sub-Saharan Africa)}\vspace{16pt}
  }}
  \end{center}
  \vspace{16pt}
  \begin{center}
  \colorbox{accent!20!bgposter}{\parbox{0.92\linewidth}{
    \centering\vspace{16pt}
    {\fontsize{60}{72}\selectfont\bfseries\color{accent} < 7 YEARS}\\[12pt]
    {\fontsize{28}{36}\selectfont \textbf{Average in South Asia \& Sub-Saharan Africa}}\vspace{16pt}
  }}
  \end{center}
  \vspace{16pt}
  \begin{center}
  \colorbox{primary!20!bgposter}{\parbox{0.92\linewidth}{
    \centering\vspace{16pt}
    {\fontsize{60}{72}\selectfont\bfseries\color{primary} 10+ YEARS}\\[12pt]
    {\fontsize{28}{36}\selectfont \textbf{High-Income Countries}}\vspace{16pt}
  }}
  \end{center}
  \vspace{24pt}
  \begin{itemize}[itemsep=12pt]
    \item Children in the poorest nations receive \textbf{less than a third} of the quality schooling available in wealthy nations.
  \end{itemize}
}

\posterbox[highlightcard, title={Key Takeaway}
]{name=col2b, column=2, between=row14 and row18}{
  \fontsize{28}{38}\selectfont
  The world has achieved remarkable progress, but the job is far from done. 
  \vspace{16pt}

  \begin{itemize}[itemsep=16pt, label={\color{textlight}$\blacktriangleright$}]
    \item Hundreds of millions of children are out of school entirely, or learning very little while attending.
    \item Closing the gap between enrollment and actual learning is one of the most pressing challenges of our time.
    \item Reducing extreme inequality between rich and poor nations remains critical.
  \end{itemize}
}

\posterbox[ambercard, title={Summary Metrics}
]{name=col2c, column=2, between=row18 and bottom}{
  \fontsize{26}{34}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \begin{center}
  \begin{tabular}{p{0.65\linewidth} >{\bfseries}p{0.25\linewidth}}
    Adults educated (1800) & < 1 in 5 \\
    \rowcolor{primary!15!bgposter} Adults educated (today) & > 4 in 5 \\
    Quality schooling (poorest) & < 3 years \\
    \rowcolor{primary!15!bgposter} Quality schooling (richest) & 10+ years \\
  \end{tabular}
  \end{center}
}

\end{tcbposter}
\end{document}

